extends CharacterBody2D
var speed = 70
@onready var anim = $AnimatedSprite2D
func _physics_process(_delta):
	var input = Vector2(Input.get_action_strength('ui_right') - Input.get_action_strength('ui_left'), Input.get_action_strength('ui_down') - Input.get_action_strength('ui_up'))
	if input.x < 0:
		anim.flip_h = true
	elif input.x > 0:
		anim.flip_h = false
	if input != Vector2.ZERO:
		anim.play('walk')
	else:
		anim.play('idle')
	velocity = input.normalized() * speed
	move_and_slide()

extends Area2D

@onready var game_over_scene = preload('res://win.tscn')

func _on_body_entered(body):
	if body.name == 'Player':
		get_tree().paused = true
		var game_over = game_over_scene.instantiate()
		get_tree().root.add_child(game_over)

extends CharacterBody2D

@onready var player = get_parent().get_node('Player')
@onready var anim = $AnimatedSprite2D
@onready var game_over_scene = preload('res://lose.tscn')

func _physics_process(_delta):
	if not player:
		return

	var dir = (player.position - position).normalized()
	velocity = dir * 50
	move_and_slide()

	if velocity.x < 0:
		anim.flip_h = true
	elif velocity.x > 0:
		anim.flip_h = false

func _on_body_entered(body):
	if body.name == 'Player':
		get_tree().paused = true
		var game_over = game_over_scene.instantiate()
		get_tree().root.add_child(game_over)

extends CanvasLayer

@onready var coin_label = $Label
var coin = 0

func coin_plus():
	coin = coin + 1
	coin_label.text = str(coin)

extends Node2D

@onready var coin_score = get_parent().get_node('CoinScore')

